import os
import torch


class Config:
    """
    Global configuration for the Digital Pathology Tumor Detection task.
    Centralizes paths, hyperparameters, and constants.
    """

    # --- Reproducibility ---
    SEED = 42

    # --- System Paths ---
    # Input directories (Read-Only)
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata File Paths (Generated by provided script)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Directories (Writeable)
    # Using 'idea_1' as the working directory for this specific approach
    WORKING_DIR = "./working/idea_1"
    SUBMISSION_DIR = "./submission"

    # Artifact Paths
    CHECKPOINT_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure necessary writeable directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # --- Data Configuration ---
    ORIGINAL_SIZE = 96
    # Strategy: Crop center 64x64 to capture the 32x32 ROI plus context
    CROP_SIZE = 64
    ROI_SIZE = 32

    # Image Normalization (ImageNet Defaults)
    MEAN = [0.485, 0.456, 0.406]
    STD = [0.229, 0.224, 0.225]

    # --- Model Configuration ---
    MODEL_NAME = "resnet18"
    PRETRAINED = True
    NUM_CLASSES = 1  # Binary classification (Tumor vs No Tumor)

    # --- Training Hyperparameters ---
    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # 12 vCPUs available, leaving some overhead
    NUM_WORKERS = 8

    # Optimization
    # A100 40GB allows for large batch sizes for small images
    BATCH_SIZE = 512
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-4
    EPOCHS = 10

    # Scheduler (Cosine Annealing)
    ETA_MIN = 1e-6

    # --- Debugging / Development ---
    # Set DEBUG to True to train on a small subset for quick pipeline verification
    DEBUG = False
    DEBUG_SUBSET_SIZE = 2000
